// Opt-in AI helpers: gig description writer, buyer brief writer, reply
// suggestions and seller matching. AI_HELPERS=off disables them.
// With AI_API_URL + AI_API_KEY (OpenAI-compatible chat completions) text is
// generated by that provider; otherwise, or on any provider error, the
// deterministic mock in utils/aiMock.js is used. Matching is always local.
const httpStatus = require("http-status");
const mongoose = require("mongoose");
const ApiError = require("../utils/ApiError");
const mock = require("../utils/aiMock");
const { PUBLIC_USER_SELECT } = require("../utils/publicUser");

const enabled = () => String(process.env.AI_HELPERS || "on").toLowerCase() !== "off";
const provider = () => (process.env.AI_API_URL && process.env.AI_API_KEY ? "remote" : "mock");
const assertOn = () => { if (!enabled()) throw new ApiError(httpStatus.SERVICE_UNAVAILABLE, "AI helpers are turned off"); };

async function remote(prompt) {
  if (provider() !== "remote") return null;
  try {
    const r = await fetch(process.env.AI_API_URL, {
      method: "POST",
      headers: { "content-type": "application/json", authorization: `Bearer ${process.env.AI_API_KEY}` },
      body: JSON.stringify({ model: process.env.AI_MODEL || "default", messages: [{ role: "user", content: prompt }], max_tokens: 500 }),
      signal: AbortSignal.timeout(15000),
    });
    const j = await r.json();
    return j?.choices?.[0]?.message?.content?.trim() || null;
  } catch { return null; }
}

async function gigDescription(body = {}) {
  assertOn();
  if (String(body.title || "").trim().length < 5) throw new ApiError(httpStatus.BAD_REQUEST, "Give a title of at least 5 characters");
  const text = await remote(`Write a friendly gig description (under 200 words) for: ${String(body.title).slice(0, 120)}. Skills: ${String(body.skills || "").slice(0, 200)}`);
  return { text: text || mock.gigDescription(body), source: text ? "remote" : "mock" };
}

async function brief(body = {}) {
  assertOn();
  const b = mock.brief(body);
  if (!b) throw new ApiError(httpStatus.BAD_REQUEST, "Describe your idea in a few words");
  const text = await remote(`Turn this idea into a clear project brief with goals and deliverables: ${String(body.idea).slice(0, 600)}`);
  return { title: b.title, description: text || b.description, source: text ? "remote" : "mock" };
}

async function replies(body = {}) {
  assertOn();
  if (!String(body.message || "").trim()) throw new ApiError(httpStatus.BAD_REQUEST, "Message is required");
  return { suggestions: mock.replySuggestions(body), source: "mock" };
}

async function match(requestId, viewer) {
  assertOn();
  const { BuyerRequest, User } = require("../models");
  if (!mongoose.isValidObjectId(requestId)) throw new ApiError(httpStatus.NOT_FOUND, "Request not found");
  const r = await BuyerRequest.findById(requestId);
  if (!r) throw new ApiError(httpStatus.NOT_FOUND, "Request not found");
  if (String(r.buyerId) !== String(viewer.id)) throw new ApiError(httpStatus.FORBIDDEN, "Only the request owner can see matches");
  const sellers = await User.find({ role: "freelancer", isDeleted: { $ne: true }, bannedAt: null }).select(PUBLIC_USER_SELECT).limit(500);
  const text = `${r.title} ${r.description}`;
  const results = sellers.map((s) => ({ seller: s, score: mock.matchScore(text, s) }))
    .filter((x) => x.score > 0).sort((a, b) => b.score - a.score).slice(0, 10);
  return { results };
}

// Raw completion through the configured provider (null if none).
const complete = (prompt) => remote(prompt);

module.exports = { complete, gigDescription, brief, replies, match, enabled, provider };
